using System.Windows;
using System.Windows.Automation;
using System.Windows.Input;
using System.Windows.Media;
using PCManager.Core.Design;
using PCManager.Motion;

namespace PCManager.Controls;

/// <summary>Which palette family an <see cref="Icon3D"/> draws with.</summary>
public enum Icon3DTint
{
    Gold,
    Neutral,
    Success,
    Warning,
    Critical
}

/// <summary>
/// Layered-vector 3D icon (plan U2). The geometry comes from Assets/Icons3D*.xaml, generated by
/// tools/IconGen; the shadow, extrusion, gradient face, specular highlight and rim are composed
/// once per (icon, tint, theme, detail level) and frozen, then scaled to any DPI.
///
/// Detail level follows <see cref="Size"/>: Small (flat gradient, 16-24 px), Medium (extrusion and
/// specular band, 28-52 px) and Large (shadow, deeper extrusion, crescent and rim, 56 px and up).
/// Icons never replace a label: automation falls back to the icon key.
/// </summary>
public sealed class Icon3D : FrameworkElement
{
    private static readonly List<WeakReference<Icon3D>> LiveIcons = new();

    private readonly RotateTransform _tilt = new();

    public Icon3D()
    {
        RenderTransform = _tilt;
        RenderTransformOrigin = new Point(0.5, 0.5);
        Focusable = false;
        SnapsToDevicePixels = true;
        UseLayoutRounding = true;

        Loaded += OnLoaded;
        MouseEnter += OnHoverChanged;
        MouseLeave += OnHoverChanged;
    }

    public static readonly DependencyProperty KeyProperty = DependencyProperty.Register(
        nameof(Key),
        typeof(string),
        typeof(Icon3D),
        new FrameworkPropertyMetadata(string.Empty, FrameworkPropertyMetadataOptions.AffectsRender, OnKeyChanged));

    public static readonly DependencyProperty SizeProperty = DependencyProperty.Register(
        nameof(Size),
        typeof(double),
        typeof(Icon3D),
        new FrameworkPropertyMetadata(
            32d,
            FrameworkPropertyMetadataOptions.AffectsMeasure | FrameworkPropertyMetadataOptions.AffectsRender),
        value => value is double d && d >= 0 && d <= 512);

    public static readonly DependencyProperty TintProperty = DependencyProperty.Register(
        nameof(Tint),
        typeof(Icon3DTint),
        typeof(Icon3D),
        new FrameworkPropertyMetadata(Icon3DTint.Gold, FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty AnimatedProperty = DependencyProperty.Register(
        nameof(Animated),
        typeof(bool),
        typeof(Icon3D),
        new FrameworkPropertyMetadata(false));

    /// <summary>Inventory name without the Icon3D. prefix, e.g. "Memory" or "Icon3D.Memory".</summary>
    public string Key
    {
        get => (string)GetValue(KeyProperty);
        set => SetValue(KeyProperty, value);
    }

    /// <summary>Square edge in device-independent pixels; also selects the detail level.</summary>
    public double Size
    {
        get => (double)GetValue(SizeProperty);
        set => SetValue(SizeProperty, value);
    }

    public Icon3DTint Tint
    {
        get => (Icon3DTint)GetValue(TintProperty);
        set => SetValue(TintProperty, value);
    }

    /// <summary>Opt-in ±3° hover tilt. Ignored when Windows animations are switched off.</summary>
    public bool Animated
    {
        get => (bool)GetValue(AnimatedProperty);
        set => SetValue(AnimatedProperty, value);
    }

    /// <summary>True when the theme dictionary currently on screen is the dark one.</summary>
    public static bool IsDarkTheme
    {
        get
        {
            if (Application.Current?.TryFindResource("App.Background") is SolidColorBrush background)
            {
                Color color = background.Color;
                double luminance = ((0.2126 * color.R) + (0.7152 * color.G) + (0.0722 * color.B)) / 255d;
                return luminance < 0.5;
            }

            return false;
        }
    }

    /// <summary>
    /// ThemeService calls this after swapping the dictionary: the composed drawings bake the
    /// palette, so the cache and every live icon must be refreshed.
    /// </summary>
    public static void NotifyThemeChanged()
    {
        Icon3DRenderer.ClearCache();

        for (int i = LiveIcons.Count - 1; i >= 0; i--)
        {
            if (LiveIcons[i].TryGetTarget(out Icon3D? icon))
            {
                icon.InvalidateVisual();
            }
            else
            {
                LiveIcons.RemoveAt(i);
            }
        }
    }

    protected override System.Windows.Size MeasureOverride(System.Windows.Size availableSize) =>
        new(Size, Size);

    protected override void OnRender(DrawingContext drawingContext)
    {
        double size = Size;

        if (size <= 0)
        {
            return;
        }

        string name = IconMetrics.NormalizeKey(Key);

        if (name.Length == 0)
        {
            return;
        }

        DrawingImage? image = Icon3DRenderer.Get(name, IconMetrics.ForSize(size), Tint, IsDarkTheme);

        if (image is null)
        {
            return;
        }

        drawingContext.DrawImage(image, new Rect(0, 0, size, size));
    }

    private static void OnKeyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        var icon = (Icon3D)d;
        string name = IconMetrics.NormalizeKey(e.NewValue as string);

        AutomationProperties.SetName(icon, IconMetrics.AutomationName(name));
        icon.InvalidateVisual();
    }

    private void OnLoaded(object sender, RoutedEventArgs e)
    {
        foreach (WeakReference<Icon3D> reference in LiveIcons)
        {
            if (reference.TryGetTarget(out Icon3D? existing) && ReferenceEquals(existing, this))
            {
                return;
            }
        }

        LiveIcons.Add(new WeakReference<Icon3D>(this));
    }

    private void OnHoverChanged(object sender, MouseEventArgs e)
    {
        bool hovered = e.RoutedEvent == MouseEnterEvent;

        if (!Animated)
        {
            _tilt.BeginAnimation(RotateTransform.AngleProperty, null);
            _tilt.Angle = 0;
            return;
        }

        Motion.Motion.Tilt3D(_tilt, hovered ? 3d : 0d);
    }
}
